import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversation;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversationParam;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversationResult;
import com.alibaba.dashscope.common.MultiModalMessage;
import com.alibaba.dashscope.common.Role;
import com.alibaba.dashscope.exception.ApiException;
import com.alibaba.dashscope.exception.NoApiKeyException;
import com.alibaba.dashscope.exception.UploadFileException;
import com.alibaba.dashscope.utils.Constants;
import com.alibaba.dashscope.utils.JsonUtils;

public class Main {
  public static void simpleMultiModalConversationCall()
      throws ApiException, NoApiKeyException, UploadFileException {
    MultiModalConversation conv = new MultiModalConversation();
    MultiModalMessage userMessage = MultiModalMessage.builder()
        .role(Role.USER.getValue())
        .content(Arrays.asList(
            Collections.singletonMap("audio", "https://dashscope.oss-cn-beijing.aliyuncs.com/audios/welcome.mp3")))
        .build();

    MultiModalMessage sysMessage = MultiModalMessage.builder().role(Role.SYSTEM.getValue())
        // 在此处配置自定义识别的上下文
        .content(Arrays.asList(Collections.singletonMap("text", "")))
        .build();

    Map<String, Object> asrOptions = new HashMap<>();
    asrOptions.put("enable_itn", false);
    // asrOptions.put("language", "zh"); // 可选。若已知音频语言，可指定此参数以提高识别准确率。
    MultiModalConversationParam param = MultiModalConversationParam.builder()
        // 如果您尚未配置环境变量，请将以下代码行替换为您的 API Key：.apiKey("sk-xxx")
        .apiKey(System.getenv("DASHSCOPE_API_KEY"))
        .model("qwen3-asr-flash")
        .message(sysMessage)
        .message(userMessage)
        .parameter("asr_options", asrOptions)
        .build();
    MultiModalConversationResult result = conv.call(param);
    System.out.println(JsonUtils.toJson(result));
  }
  public static void main(String[] args) {
    try {
      Constants.baseHttpApiUrl = "https://dashscope.aliyuncs.com/api/v1";
      simpleMultiModalConversationCall();
    } catch (ApiException | NoApiKeyException | UploadFileException e) {
      System.out.println(e.getMessage());
    }
    System.exit(0);
  }
}

